(()=>{'use strict';let record=null,pending=null;const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(path='/api/learner',body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',signal:controller.signal,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify({self:record?.self,...body}):undefined});const result=await r.json();if(!r.ok)throw Error(result.error||'Learner features could not load.');if(record&&result.self&&record.self!==result.self)throw Error('Your account changed. Reload before continuing.');if(result.preferences){record=result;updateAvatars();}return result;}finally{clearTimeout(timer);}}async function load(){if(record)return record;if(!pending)pending=api().finally(()=>pending=null);return pending;}function updateAvatars(){for(const id of ['header-avatar','profile-avatar']){const el=document.getElementById(id);if(!el)continue;if(record?.photoUrl){const img=document.createElement('img');img.src=record.photoUrl;img.alt='Your profile photo';img.className='learner-avatar-image';el.replaceChildren(img);el.classList.add('has-profile-photo');}else if(el.classList.contains('has-profile-photo')){el.classList.remove('has-profile-photo');el.textContent='CT';}}}async function track(kind,courseId='',query=''){try{const r=await load();if(!r.preferences.personalize)return;await api('/api/learner',{action:'signal',kind,courseId,query,epoch:r.recEpoch});}catch{}}
async function suggestions(target){if(!target)return;try{await load();const r=await api('/api/recommendations');target.innerHTML=`<div class="suggestion-heading"><div><p class="eyebrow">${r.personalized?'PERSONALIZED FOR YOU':'A PLACE TO BEGIN'}</p><h2>Your next step</h2></div>${!r.personalized?'<button class="button outline" data-enable-personalization>Personalize suggestions</button>':'<a href="/profile#learner-settings">Manage personalization ↗</a>'}</div><div class="suggestions-grid">${r.recommendations.slice(0,2).map(c=>`<a class="suggestion-card" href="${esc(c.link)}"><span class="tag">${esc(c.level)}</span><h3>${esc(c.title)}</h3><p>${esc(c.reason)}</p><span>Explore this course ↗</span></a>`).join('')}</div><p class="discovery-small">Suggestions help you explore; they are not a skill assessment. Check each course’s prerequisites. ${r.personalized?'Uses your opted-in course searches, views and saved learning activity.':'Personalization is off. Turn it on to use your course searches and learning activity.'}</p>`;target.querySelector('[data-enable-personalization]')?.addEventListener('click',async e=>{e.target.disabled=true;try{await api('/api/learner',{action:'personalize',enabled:true});await suggestions(target);}catch(err){e.target.disabled=false;target.insertAdjacentHTML('beforeend','<p role="status">'+esc(err.message)+'</p>');}});}catch{target.innerHTML='<p class="muted">Suggestions are temporarily unavailable. Your course progress is unchanged.</p>';}}
async function renderProfile(target){try{const r=await load(),p=r.preferences;target.innerHTML=`<div class="section-head"><h2>Photo, discovery & personalization</h2></div><div class="learner-settings-grid"><section class="panel photo-panel"><div class="avatar photo-preview" id="learner-photo-preview">${r.photoUrl?`<img class="learner-avatar-image" src="${esc(r.photoUrl)}" alt="Your profile photo">`:'CT'}</div><h3>Your profile photo</h3><p>Choose a photo from your device. It is cropped to a square, resized and stripped of metadata before upload.</p><label class="button outline photo-file-label">Choose photo<input id="profile-photo-file" type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,.jpg,.jpeg,.png,.webp,.heic,.heif" aria-label="Choose profile photo"></label><div class="button-row"><button class="button" id="save-profile-photo" disabled>Save photo</button><button class="button outline" id="remove-profile-photo" ${r.photoUrl?'':'disabled'}>Remove photo</button></div><p class="discovery-small">JPG, PNG, WebP or iCloud HEIC/HEIF · Up to 20 MB. Only a small processed thumbnail is saved to your account. HEIC conversion stays on your device; its decoder loads from a public CDN when needed. Other learners see it only when you enable photo visibility and directory discovery.</p><p class="form-status" id="photo-status" role="status"></p></section><section class="panel"><form id="learner-settings-form"><label class="field">Name shown to other learners<input id="learner-public-name" maxlength="60" value="${esc(p.publicName)}" placeholder="Choose your public learner name"><small>Only shown when directory discovery is enabled. Your email is never listed. Course-community discovery is controlled separately inside each community.</small></label><label class="field">City or region<input id="learner-location" maxlength="80" value="${esc(p.location)}" placeholder="For example, Philadelphia, PA"><small>Optional and self-entered. Do not include a street address. We do not request GPS location.</small></label><label class="preference-check"><input id="learner-discoverable" type="checkbox" ${p.discoverable?'checked':''}><span>Let signed-in learners find my public name in the learner directory</span></label><label class="preference-check"><input id="learner-show-location" type="checkbox" ${p.shareLocation?'checked':''}><span>When discoverable, show my city or region and allow searching by it</span></label><label class="preference-check"><input id="learner-show-photo" type="checkbox" ${p.sharePhoto?'checked':''}><span>When discoverable, show my profile photo to other signed-in learners</span></label><label class="preference-check"><input id="learner-personalize" type="checkbox" ${p.personalize?'checked':''}><span>Personalize course suggestions using my course searches, views and saved learning activity</span></label><p class="discovery-small">Up to 30 recent course searches and views are retained when enabled. Learner-directory searches are not recorded. Turning personalization off clears this search/view history; your course progress stays saved.</p><button class="button" id="save-learner-settings">Save preferences</button><button class="button outline" type="button" id="clear-rec-history">Clear recommendation history</button><p class="form-status" id="learner-settings-status" role="status"></p></form><a class="text-link" href="/people">Find other learners ↗</a></section></div>`;let photo=null,photoGeneration=0,dirty=false,preferenceRevision=r.preferenceRevision;const form=target.querySelector('#learner-settings-form'),status=target.querySelector('#learner-settings-status'),photoStatus=target.querySelector('#photo-status');form.oninput=()=>{dirty=true;status.textContent='Unsaved preferences';};form.onsubmit=async e=>{e.preventDefault();const controls=[...form.querySelectorAll('input,button')];controls.forEach(x=>x.disabled=true);try{await api('/api/learner',{action:'preferences',preferenceRevision,preferences:{publicName:target.querySelector('#learner-public-name').value,location:target.querySelector('#learner-location').value,discoverable:target.querySelector('#learner-discoverable').checked,shareLocation:target.querySelector('#learner-show-location').checked,sharePhoto:target.querySelector('#learner-show-photo').checked,personalize:target.querySelector('#learner-personalize').checked}});preferenceRevision=record.preferenceRevision;dirty=false;status.textContent='Privacy and personalization preferences saved.';}catch(err){status.textContent=err.message;}finally{controls.forEach(x=>x.disabled=false);}};target.querySelector('#clear-rec-history').onclick=async()=>{if(!confirm('Clear your saved course search and view history? Course progress and saved code will stay.'))return;try{await api('/api/learner',{action:'clearSignals'});status.textContent='Recommendation search/view history cleared. Suggestions may still use saved course progress when personalization is enabled.';}catch(err){status.textContent=err.message;}};const file=target.querySelector('#profile-photo-file'),save=target.querySelector('#save-profile-photo'),remove=target.querySelector('#remove-profile-photo');file.onchange=async()=>{const f=file.files?.[0];if(!f)return;file.value='';const generation=++photoGeneration;photo=null;save.disabled=true;photoStatus.textContent='Preparing a private preview…';try{const prepared=await preparePhoto(f);if(generation!==photoGeneration)return;photo=prepared;target.querySelector('#learner-photo-preview').innerHTML='<img class="learner-avatar-image" alt="New photo preview" src="'+photo+'">';save.disabled=false;photoStatus.textContent='Preview only. Choose Save photo to upload it.';}catch(err){if(generation===photoGeneration)photoStatus.textContent=err.message;}};save.onclick=async()=>{if(!photo)return;file.disabled=save.disabled=remove.disabled=true;photoStatus.textContent='Uploading photo…';try{await api('/api/learner',{action:'photo',dataUrl:photo,photoRevision:record.photoRevision});photo=null;target.querySelector('#learner-photo-preview').innerHTML='<img class="learner-avatar-image" alt="Your saved profile photo" src="'+esc(record.photoUrl)+'">';photoStatus.textContent='Photo saved to your account.';}catch(err){photoStatus.textContent=err.message;}finally{file.disabled=false;save.disabled=!photo;remove.disabled=!record?.photoUrl;}};remove.onclick=async()=>{if(!confirm('Remove your profile photo?'))return;photoGeneration++;photo=null;file.disabled=save.disabled=remove.disabled=true;try{await api('/api/learner',{action:'removePhoto',photoRevision:record.photoRevision});photo=null;target.querySelector('#learner-photo-preview').textContent='CT';photoStatus.textContent='Profile photo removed.';}catch(err){photoStatus.textContent=err.message;}finally{file.disabled=false;save.disabled=!photo;remove.disabled=!record?.photoUrl;}};addEventListener('beforeunload',e=>{if(dirty||photo){e.preventDefault();e.returnValue='';}});}catch(e){target.innerHTML='<div class="notice error">'+esc(e.message)+'</div>';}}
let heicModule=null;
async function preparePhoto(file){if(/\.icloud$/i.test(file.name||''))throw Error('Download the original photo from iCloud to your device, then select that image.');if(!file.size)throw Error('This iCloud item has not downloaded yet. Download it to your device, then choose it again.');if(file.size>20*1024*1024)throw Error('Choose a photo under 20 MB. Large photos are reduced before upload.');const head=new Uint8Array(await file.slice(0,64).arrayBuffer()),ascii=(at,n)=>String.fromCharCode(...head.slice(at,at+n));const jpeg=head[0]===255&&head[1]===216&&head[2]===255,png=head[0]===137&&ascii(1,3)==='PNG',webp=ascii(0,4)==='RIFF'&&ascii(8,4)==='WEBP';const heic=ascii(4,4)==='ftyp'&&/heic|heix|hevc|hevx|mif1|msf1/.test(ascii(8,56));const heicHint=/\.(heic|heif)$/i.test(file.name||'')||/image\/(heic|heif)/i.test(file.type||'');if(!jpeg&&!png&&!webp&&!heic&&!heicHint)throw Error('Choose a JPG, PNG, WebP, HEIC or HEIF photo. This file does not look like a supported image.');const canonicalType=jpeg?'image/jpeg':png?'image/png':webp?'image/webp':'image/heic';let source=file.type===canonicalType?file:new Blob([file],{type:canonicalType});const urls=[];async function decode(blob){const objectURL=URL.createObjectURL(blob);urls.push(objectURL);const img=new Image();await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('The photo took too long to open. Make sure the original is downloaded from iCloud and try again.')),30000);img.onload=()=>{clearTimeout(timeout);resolve();};img.onerror=()=>{clearTimeout(timeout);reject(Error('Photo decoding failed.'));};img.src=objectURL;});return img;}try{let img;try{img=await decode(source);}catch(error){if(!heic&&!heicHint)throw Error('This photo could not be opened. Download the full original from iCloud, or export it as JPG/PNG and try again.');const status=document.getElementById('photo-status');if(status)status.textContent='Converting the iCloud HEIC photo on your device… The first conversion downloads the decoder.';try{if(!heicModule)heicModule=import('https://cdn.jsdelivr.net/npm/heic-to@1.6.5/csp/+esm').catch(e=>{heicModule=null;throw e;});const module=await heicModule;source=await module.heicTo({blob:source,type:'image/jpeg',quality:.9});img=await decode(source);}catch{throw Error('This HEIC photo could not be converted on this device. Try again with a stable connection, or export the photo from Photos as JPG/PNG. Your original was not uploaded.');}}if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth>16000||img.naturalHeight>16000||img.naturalWidth*img.naturalHeight>100000000)throw Error('This photo is over 100 megapixels or 16,000 pixels per side. Export a smaller copy.');const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d');const crop=Math.min(img.naturalWidth,img.naturalHeight);ctx.drawImage(img,(img.naturalWidth-crop)/2,(img.naturalHeight-crop)/2,crop,crop,0,0,256,256);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.82));if(!blob)throw Error('Your browser could not prepare this photo.');if(blob.size>175000){const small=document.createElement('canvas');small.width=small.height=192;small.getContext('2d').drawImage(canvas,0,0,192,192);blob=await new Promise(resolve=>small.toBlob(resolve,'image/webp',.75));}if(!blob||blob.size>180000||!['image/webp','image/png'].includes(blob.type))throw Error('The processed thumbnail could not be prepared. Try another photo.');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Photo processing failed.'));reader.readAsDataURL(blob);});}finally{for(const url of urls)URL.revokeObjectURL(url);}}

async function directory(target){target.innerHTML=`<p class="eyebrow">FIND YOUR STUDY CIRCLE</p><h1 class="page-title">MEET OTHER LEARNERS.</h1><p class="page-subtitle">Search people who chose to be discoverable. Location is shown and searchable only when that learner allows it.</p><form class="directory-filters" id="directory-form"><label class="field">Learner name<input id="people-name" type="search" maxlength="80" placeholder="Search a display name"></label><label class="field">City or region<input id="people-location" type="search" maxlength="80" placeholder="Optional location"></label><button class="button">Find learners ↗</button></form><p class="discovery-small">Directory searches are not used for course recommendations. <a href="/profile#learner-settings">Manage your own visibility ↗</a></p><div id="directory-status" class="form-status" role="status"></div><div id="directory-results" class="people-grid"></div>`;let serial=0;const courseNames={'python-dsa':'Python & Data Structures','java-basics':'Java Basics','ai-foundations':'AI Foundations','python-for-ai':'Python for AI','ml-foundations':'Machine Learning','llm-rag':'LLMs & Retrieval','agentic-ai':'Agentic AI','production-ai':'Reliable AI Systems'};async function search(){const id=++serial;target.querySelector('#directory-status').textContent='Finding learners…';try{await load();const r=await api('/api/learners?q='+encodeURIComponent(target.querySelector('#people-name').value)+'&location='+encodeURIComponent(target.querySelector('#people-location').value));if(id!==serial)return;target.querySelector('#directory-status').textContent=r.learners.length?'Showing '+r.learners.length+' discoverable learners'+(r.learners.length===r.limit?' (narrow your search for more specific matches)':''):'No matching discoverable learners yet.';target.querySelector('#directory-results').innerHTML=r.learners.map(p=>`<article class="person"><div class="avatar small directory-avatar">${p.photoUrl?`<img class="learner-avatar-image" src="${esc(p.photoUrl)}" alt="Profile photo of ${esc(p.name)}" loading="lazy">`:esc(p.name.slice(0,2).toUpperCase())}</div><h3>${esc(p.name)}</h3>${p.location?'<p>⌖ '+esc(p.location)+'</p>':'<p>Location not shared</p>'}${p.commonCourses.length?'<p>You can connect in:</p>'+p.commonCourses.map(id=>`<a class="button outline" href="/community?course=${encodeURIComponent(id)}#learners">${esc(courseNames[id]||id)} ↗</a>`).join(''):'<p class="discovery-small">Study connections are available when you share a course community and the learner enables course discovery.</p>'}</article>`).join('');target.querySelectorAll('.directory-avatar img').forEach(img=>img.onerror=()=>{img.parentElement.textContent='CT';});}catch(e){if(id===serial)target.querySelector('#directory-status').textContent=e.message;}}target.querySelector('#directory-form').onsubmit=e=>{e.preventDefault();search();};await search();}
let searchTimer,lastSearch='',viewed=new Set();function trackSearch(query){clearTimeout(searchTimer);const q=query.trim();if(q.length<3||q===lastSearch)return;searchTimer=setTimeout(()=>{lastSearch=q;track('search','',q);},1000);}function trackView(course){if(viewed.has(course))return;viewed.add(course);track('view',course,'');}
window.LearnerFeatures={load,track,trackSearch,trackView,suggestions,renderProfile,directory,updateAvatars};load().catch(()=>{});
})();
